    function setUp() public {
        c = new Owned();
    }

    function _run(address caller, address newOwner) internal {
        vm.assume(c.owner() == address(this));
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.owner() == newOwner);
    }

